}

function buildKeystoneProducts() {
  const config = getControlConfig();
  const records = fixedRecords();
  const store = telemetryStore();
  const isMini = detectMini(records, config);
  const pcsMd = isMini ? 'eSpire-Mini-PCS' : 'eSpire-PCS';
  const bmsMd = isMini ? 'eSpire-Mini-BMS' : 'eSpire-BMS';
  let pcsSn = '';
  let sfver = '';
  let dspsfver = '';
  for (const fixed of records) {
    const id = Number(fixed.ID);
    if ((id >= 40100 && id <= 40104) || id === 50103) {
      pcsSn = normalizeSerial(fixed.SN) || pcsSn;
      sfver = fixed.SFVER || fixed.ARM || sfver;
      dspsfver = fixed.DSPSFVER || fixed.DSP || dspsfver;
      if (pcsSn) break;
    }
  }
  pcsSn = manualPcsSerial(config) || pcsSn;
  if (!pcsSn) pcsSn = serialFromTelemetry(store, ['PCS', 'Delta_PCS', 'Sinexcel_PCS']) || normalizeSerial(getAnyContext(global, 'pcsSerialNumber') || getAnyContext(global, 'PCS_SN'));
  const products = [];
  if (pcsSn) products.push(product('fortress', pcsMd, pcsMd, pcsSn, 'Inverter', { SFVER: sfver, DSPSFVER: dspsfver, Role: 1 }));
  const batterySns = new Set();
  for (const fixed of records) {
    const id = Number(fixed.ID);
    if ((id >= 42100 && id <= 42104) || id === 52103) {
      const sn = normalizeSerial(fixed.SN);
      if (sn) batterySns.add(sn);
    }
  }
  for (const key of Object.keys(store || {}).filter((name) => /bcu|sbmu|battery/i.test(name))) {
    if (isMini) {
      const bcuMatch = String(key).match(/(?:^|_)BCU_(\d+)$/i);
      if (!bcuMatch || Number(bcuMatch[1]) > 2) continue;
    }
    const sn = serialFromTelemetry(store, [key]);
    if (sn) batterySns.add(sn);
  }
  for (const sn of manualBatterySerials(config)) batterySns.add(sn);
  const configuredBatterySns = getAnyContext(global, 'batterySerialNumbers') || config?.equipment?.batterySerialNumbers || config?.batteries;
  if (Array.isArray(configuredBatterySns)) {
    for (const item of configuredBatterySns) {
      const sn = normalizeSerial(typeof item === 'object' ? (item.sn || item.SN || item.serialNumber) : item);
      if (sn) batterySns.add(sn);
    }
  }
  const batteryProductSerials = isMini ? Array.from(batterySns).slice(0, 2) : Array.from(batterySns);
  for (const sn of batteryProductSerials) products.push(product('fortress', bmsMd, bmsMd, sn, 'Battery'));
  return products;
}

