const CRON_MONTHS = { JAN: 1, FEB: 2, MAR: 3, APR: 4, MAY: 5, JUN: 6, JUL: 7, AUG: 8, SEP: 9, OCT: 10, NOV: 11, DEC: 12 };
const CRON_DAYS = { SUN: 0, MON: 1, TUE: 2, WED: 3, THU: 4, FRI: 5, SAT: 6 };

function cronRange(kind) {
  if (kind === 'second' || kind === 'minute') return { min: 0, max: 59 };
  if (kind === 'hour') return { min: 0, max: 23 };
  if (kind === 'dayOfMonth') return { min: 1, max: 31 };
  if (kind === 'month') return { min: 1, max: 12 };
  if (kind === 'dayOfWeek') return { min: 0, max: 7 };
  return { min: 1970, max: 2099 };
}

function parseCronToken(token, kind) {
  const text = String(token || '').trim().toUpperCase();
  if (text === '*' || text === '?') return undefined;
  if (kind === 'month' && CRON_MONTHS[text] != null) return CRON_MONTHS[text];
  if (kind === 'dayOfWeek' && CRON_DAYS[text] != null) return CRON_DAYS[text];
  const value = Number(text);
  if (!Number.isFinite(value)) return undefined;
  if (kind === 'dayOfWeek' && value === 7) return 0;
  return value;
}

function expandCronField(field, kind) {
  const text = String(field || '').trim();
  if (!text || text === '*') return null;
  if (text === '?' && (kind === 'dayOfMonth' || kind === 'dayOfWeek')) return null;
  if (text === '?') return new Set();
  const range = cronRange(kind);
  const values = new Set();
  for (const raw of text.split(',')) {
    const token = raw.trim();
    if (!token) return new Set();
    const parts = token.split('/');
    const base = parts[0];
    const step = parts[1] === undefined ? 1 : Number(parts[1]);
    if (!Number.isInteger(step) || step <= 0) return new Set();
    let start;
    let end;
    if (base === '*' || base === '?') {
      if (base === '?' && kind !== 'dayOfMonth' && kind !== 'dayOfWeek') return new Set();
      start = range.min;
      end = range.max;
    } else if (base.includes('-')) {
      const bounds = base.split('-');
      start = parseCronToken(bounds[0], kind);
      end = parseCronToken(bounds[1], kind);
      if (start == null || end == null || start > end) return new Set();
    } else {
      start = parseCronToken(base, kind);
      end = start;
      if (start == null) return new Set();
    }
    for (let value = start; value <= end; value += step) {
      if (!Number.isInteger(value) || value < range.min || value > range.max) return new Set();
      values.add(kind === 'dayOfWeek' && value === 7 ? 0 : value);
    }
  }
  return values;
}

function cronFieldMatches(field, value, kind) {
  const values = expandCronField(field, kind);
  return values === null || values.has(kind === 'dayOfWeek' && value === 7 ? 0 : value);
}

function parseCronExpr(expr) {
  if (!expr || typeof expr !== 'string') return null;
  const input = expr.trim().split(/\s+/);
  const fields = input.length === 5 ? ['0'].concat(input) : input;
  if (fields.length !== 6 && fields.length !== 7) return null;
  const cron = { second: fields[0], minute: fields[1], hour: fields[2], dayOfMonth: fields[3], month: fields[4], dayOfWeek: fields[5], year: fields[6] };
  for (const [field, kind] of [[cron.second, 'second'], [cron.minute, 'minute'], [cron.hour, 'hour'], [cron.dayOfMonth, 'dayOfMonth'], [cron.month, 'month'], [cron.dayOfWeek, 'dayOfWeek']]) {
    const values = expandCronField(field, kind);
    if (values !== null && values.size === 0) return null;
  }
  if (cron.year !== undefined) {
    const values = expandCronField(cron.year, 'year');
    if (values !== null && values.size === 0) return null;
  }
  return cron;
}

function localParts(date, timezone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    weekday: 'short', hourCycle: 'h23'
  }).formatToParts(date);
  const value = (type) => parts.find((part) => part.type === type)?.value || '0';
  return {
    year: Number(value('year')),
    month: Number(value('month')),
    day: Number(value('day')),
    hour: Number(value('hour')),
    minute: Number(value('minute')),
    second: Number(value('second')),
    weekday: CRON_DAYS[String(value('weekday')).toUpperCase()] ?? 0
  };
}

function localMsFromParts(parts) {
  return Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second);
}

function partsFromLocalMs(ms) {
  const date = new Date(ms);
  return {
    year: date.getUTCFullYear(),
    month: date.getUTCMonth() + 1,
    day: date.getUTCDate(),
    hour: date.getUTCHours(),
    minute: date.getUTCMinutes(),
    second: date.getUTCSeconds(),
    weekday: date.getUTCDay()
  };
}

function cronMatchesLocalMs(cron, localMs) {
  const parts = partsFromLocalMs(localMs);
  return cronFieldMatches(cron.second, parts.second, 'second')
    && cronFieldMatches(cron.minute, parts.minute, 'minute')
    && cronFieldMatches(cron.hour, parts.hour, 'hour')
    && cronFieldMatches(cron.dayOfMonth, parts.day, 'dayOfMonth')
    && cronFieldMatches(cron.month, parts.month, 'month')
    && cronFieldMatches(cron.dayOfWeek, parts.weekday, 'dayOfWeek')
    && (cron.year === undefined || cronFieldMatches(cron.year, parts.year, 'year'));
}

function cronSeconds(cron) {
  const values = expandCronField(cron.second, 'second');
  return Array.from(values || new Set(Array.from({ length: 60 }, (_, index) => index))).sort((a, b) => a - b);
}

function findPreviousCronStart(cron, nowLocalMs, durationSec) {
  const seconds = cronSeconds(cron);
  const lookbackMs = Math.max(0, Number(durationSec || 0) * 1000);
  const firstMinute = Math.floor((nowLocalMs - lookbackMs) / 60000);
  const lastMinute = Math.floor(nowLocalMs / 60000);
  let best = null;
  for (let minute = firstMinute; minute <= lastMinute; minute += 1) {
    const minuteMs = minute * 60000;
    for (const second of seconds) {
      const candidateMs = minuteMs + second * 1000;
      if (candidateMs > nowLocalMs || candidateMs < nowLocalMs - lookbackMs) continue;
      if (cronMatchesLocalMs(cron, candidateMs)) best = candidateMs;
    }
  }
  return best;
}

function findNextCronStart(cron, nowLocalMs, horizonDays) {
  const seconds = cronSeconds(cron);
  const firstMinute = Math.floor(nowLocalMs / 60000);
  const lastMinute = firstMinute + (Number(horizonDays || 366) * 24 * 60);
  for (let minute = firstMinute; minute <= lastMinute; minute += 1) {
    const minuteMs = minute * 60000;
    for (const second of seconds) {
      const candidateMs = minuteMs + second * 1000;
      if (candidateMs <= nowLocalMs) continue;
      if (cronMatchesLocalMs(cron, candidateMs)) return candidateMs;
    }
  }
  return null;
}

function timezoneOffsetMs(epochMs, timezone) {
  return localMsFromParts(localParts(new Date(epochMs), timezone)) - epochMs;
}

function localWallMsToEpochSec(localWallMs, timezone) {
  let guess = localWallMs;
  for (let index = 0; index < 4; index += 1) {
    guess = localWallMs - timezoneOffsetMs(guess, timezone);
  }
  return Math.floor(guess / 1000);
}

function jobRuntime(job, state) {
  const now = nowSec();
  const duration = Number(job.durationSec || job.duration || 0) || 0;
  const createTs = Number(job.createTs || now);
  const base = {
    revision: Number(job.revision || 1),
    state: state || job.state || 'PENDING',
    createTs,
    lastStartTs: Number(job.lastStartTs || 0),
    lastEndTs: Number(job.lastEndTs || 0),
    nextStartTs: 0,
    nextEndTs: 0,
    executeCount: Number(job.executeCount || 0),
    failCount: Number(job.failCount || 0),
    lastError: Number(job.lastError || 0),
    lastErrorMsg: job.lastErrorMsg || 'Success',
    expired: false
