  if (base.state === 'Stopped' || base.state === 'STOPPED') return Object.assign(base, job.runtime || {}, { state: 'Stopped' });
  if (Number(job.expireTs || 0) > 0 && now >= Number(job.expireTs)) return Object.assign(base, job.runtime || {}, { state: 'Expired', expired: true });

  const execType = String(job.execType || 'Once');
