    const cron = parseCronExpr(job.cronExpr);
    if (!cron) return Object.assign(base, job.runtime || {}, { state: 'Stopped', lastError: 0x0216, lastErrorMsg: 'Invalid cron' });
    const timezone = job.timezone || controllerTimezone();
    const nowLocalMs = localMsFromParts(localParts(new Date(now * 1000), timezone));
    const previousLocalMs = duration ? findPreviousCronStart(cron, nowLocalMs, duration) : null;
    if (previousLocalMs != null && nowLocalMs >= previousLocalMs && nowLocalMs < previousLocalMs + duration * 1000) {
      const startSec = localWallMsToEpochSec(previousLocalMs, timezone);
      const endSec = localWallMsToEpochSec(previousLocalMs + duration * 1000, timezone);
      base.state = 'Running';
      base.lastStartTs = base.lastStartTs || startSec;
      base.nextStartTs = startSec;
      base.nextEndTs = endSec;
    } else {
      const nextLocalMs = findNextCronStart(cron, nowLocalMs);
      base.state = 'Pending';
      base.nextStartTs = nextLocalMs == null ? 0 : localWallMsToEpochSec(nextLocalMs, timezone);
      base.nextEndTs = nextLocalMs == null || !duration ? 0 : localWallMsToEpochSec(nextLocalMs + duration * 1000, timezone);
    }
    return Object.assign(base, job.runtime || {});
  }

  const start = Number(job.startTs || 0) || createTs;
  const end = duration ? start + duration : 0;
  base.nextStartTs = now < (end || start) ? start : 0;
  base.nextEndTs = now < (end || start) ? end : 0;
  if (execType === 'Immediate' || execType === 'Once') {
    if (duration && now >= start && now < end) base.state = 'Running';
    else if (duration && now >= end) base.state = 'Completed';
    else base.state = 'Pending';
  }
  return Object.assign(base, job.runtime || {});
}


function descForJob(job) {
  const payload = job.payload !== undefined ? job.payload : job.payloadJson;
  return Object.assign({}, job, { payload: typeof payload === 'string' ? payload : JSON.stringify(payload || {}) });
}

function jobFromData(data) {
