}

function isoFromTs(ts, fallbackTs) {
  const n = Number(ts || fallbackTs || 0);
  if (!Number.isFinite(n) || n <= 0) return iso();
  return new Date(n * 1000).toISOString();
}

function upsertJobPlan(job, state) {
  const groups = getPlans();
  const startTs = Number(job.startTs || 0) || nowSec();
  const durationSec = Number(job.durationSec || 0) || 0;
  const startIso = isoFromTs(startTs);
  const endIso = durationSec > 0 ? isoFromTs(startTs + durationSec) : startIso;
  const isCron = String(job.execType || '').toUpperCase() === 'CRON' || !!job.cronExpr;
  const plan = normalizePlan(Object.assign({}, job, {
    planID: String(job.jobId),
    name: job.jobName || `Job ${job.jobId}`,
    description: job.description || job.owner || '',
    duration: Math.max(0, Math.round(durationSec / 60)),
    start: startIso,
    until: job.expireTs ? isoFromTs(job.expireTs) : null,
    cron: job.cronExpr || null,
    time: isCron ? undefined : { start: startIso, end: endIso },
    runState: state || 'Pending',
    owner: job.owner,
    priority: job.priority,
    execType: job.execType,
    payload: job.payload,
    payloadJson: job.payloadJson,
    timezone: job.timezone
