}

function removePlanById(id) {
  const groups = getPlans();
  const next = groups
    .map((group) => Object.assign({}, group, { timed: (Array.isArray(group.timed) ? group.timed : []).filter((plan) => String(plan.planID || plan.jobId) !== String(id)) }))
    .filter((group) => (group.timed || []).length || group.default);
  publishPlans(next);
}

